script:
total_weightage = sum(frappe.utils.flt(row.weightage_) for row in doc.kra_and_goal_detail)

if total_weightage > 100:
    frappe.throw(f"Total Weightage cannot exceed 100%. Current total: {total_weightage}%")

if total_weightage != 100:
    frappe.throw(f"Total Weightage must be exactly 100% before saving. Current total: {total_weightage}%")

if not doc.kra_and_goal_setup:
    frappe.throw("Please select KRA and Goal Setup first")

kra_setup = frappe.get_doc("KRA and Goal Setup", doc.kra_and_goal_setup)

try:
    settings = frappe.get_last_doc("Performance Settings", 
        filters={"company": doc.company, "cycle_year": doc.cycle_year})
    yn = doc.cycle_year - settings.base_year + 1
except:
    settings = None
    yn = 1

if not doc.goal_progression:
    for row in kra_setup.kra_and_goal_detail:
        doc.append("goal_progression", {
            "kra_name": row.kra_name,
            "goal_name": row.kra_name + " Y" + str(yn),
            "goal_description": row.goal_description,
            "weightage_": row.get("weightage_")
        })

if not doc.self_review and settings:
    for criteria in settings.rating_criteria:
        doc.append("self_review", {
            "criteria_name": criteria.criteria_name,
            "weightage_": criteria.get("weightage_")
        })

if not doc.manager_review and settings:
    for criteria in settings.rating_criteria:
        doc.append("manager_review", {
            "criteria_name": criteria.criteria_name,
            "weightage_": criteria.get("weightage_")
        })
